package org.sleepwell.app;
import org.json.*;import java.util.*;
/** Strict private codec: v1 retains all legacy labels; v2 adds explicit six-class selection. */
final class SoundSensitivityJson {
 static String encode(SoundSensitivity value){if(!value.available())throw new IllegalArgumentException("Review sound settings before saving");try{JSONObject row=new JSONObject().put("version",2);for(String key:SoundSensitivity.CATEGORIES)row.put(key,value.windows(key));JSONObject selected=new JSONObject();for(String key:SoundSensitivity.SELECTABLE)selected.put(key,value.includes(key));return row.put("included",selected).toString();}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
 static SoundSensitivity decode(String raw){if(raw==null||raw.length()>1024)throw new IllegalArgumentException("Invalid sound analysis settings");try{JSONObject row=new JSONObject(raw);int version=whole(row.get("version"));if(version!=1&&version!=2)throw new JSONException("Unknown settings version");Set<String> keys=new HashSet<>(SoundSensitivity.CATEGORIES);keys.add("version");if(version==2)keys.add("included");if(row.length()!=keys.size())throw new JSONException("Missing sound setting");for(Iterator<String> it=row.keys();it.hasNext();)if(!keys.contains(it.next()))throw new JSONException("Unknown sound setting");Map<String,Integer> values=new LinkedHashMap<>();for(String key:SoundSensitivity.CATEGORIES)values.put(key,whole(row.get(key)));Set<String> enabled=new HashSet<>(SoundSensitivity.SELECTABLE);if(version==2){JSONObject included=row.getJSONObject("included");if(included.length()!=SoundSensitivity.SELECTABLE.size())throw new JSONException("Missing sound category");enabled.clear();for(Iterator<String> it=included.keys();it.hasNext();)if(!SoundSensitivity.SELECTABLE.contains(it.next()))throw new JSONException("Unknown sound category");for(String key:SoundSensitivity.SELECTABLE){Object value=included.get(key);if(!(value instanceof Boolean))throw new JSONException("Sound selection must be boolean");if((Boolean)value)enabled.add(key);}}return new SoundSensitivity(values,enabled);}catch(JSONException bad){throw new IllegalArgumentException("Invalid sound analysis settings",bad);}}
 private static int whole(Object value){if(!(value instanceof Number))throw new IllegalArgumentException("Sound duration must be an integer");double n=((Number)value).doubleValue();if(!Double.isFinite(n)||n!=Math.rint(n)||n<0||n>Integer.MAX_VALUE)throw new IllegalArgumentException("Invalid sound duration");return (int)n;}
}
